// Prepare data for Pinecone upsert
const inputData = $input.first().json;
const prevData = $('Split Knowledge Base Into Chunks').item.json;

const embedding = inputData.data[0].embedding;

return [{
  json: {
    id: prevData.id,
    values: embedding,
    metadata: {
      text: prevData.text,
      chunkIndex: prevData.chunkIndex,
      totalChunks: prevData.totalChunks,
      source: 'Process-Gravity-Knowledge-Base',
      version: '1.0'
    }
  }
}];

const items = $input.all();
const successful = items.filter(i => i.json.upsertedCount > 0 || i.json.upsertedCount === 0).length;

return [{
  json: {
    status: 'Knowledge base ingestion complete',
    totalChunksProcessed: items.length,
    timestamp: new Date().toISOString(),
    index: 'process-gravity-kb',
    namespace: 'process-gravity',
    nextStep: 'Run PG_Chatbot workflow to start serving queries'
  }
}];

